package com.stocksense.inventory.adjustment; import com.stocksense.inventory.stock.StockService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.Map; @RestController @RequestMapping("/api/adjustments") @RequiredArgsConstructor public class AdjustmentController { private final StockService stock; record Req(Long productId,Long locationId,BigDecimal countedQuantity,String reason){} @PostMapping("/validate") public Map<String,Object> validate(@RequestBody Req r,Authentication a){if(r.reason()==null||r.reason().isBlank())throw new IllegalArgumentException("Adjustment reason is required");stock.adjust(r.productId(),r.locationId(),r.countedQuantity(),a.getName());return Map.of("status","DONE","message","Adjustment applied and logged");} }
